            "Ebd3d3a60c4596295:0:698"
          ],
          "condicoes": [
            "Cenário específico de drenagem com descarga da bomba fechada"
          ],
          "limites": [
            "Trata-se de constatação em investigação e de cenário específico, não de regra universal para toda bomba ou toda operação de drenagem"
          ]
        },
        {
          "proposicao": "Uma salvaguarda identificada na fase de projeto pode perder efetividade operacional se não for implementada de fato ou se for convertida em prática informal e parcial.",
